/**
*  The reason a package the build variant does not carry answers with
*  (design §44 §4, D600). Every RPC of such a package refuses with it and
*  names the variant in `metadata.variant`; the runtime turns that refusal
*  into `FeatureNotInVariantError` so a caller can branch on it without
*  calling first — `loams.system.available()` answers the same question from
*  `GetInstance.services[]` without a failing call at all.
*/
export const FEATURE_NOT_IN_VARIANT = 'feature_not_in_variant' as const satisfies Reason;
